"""Compile a policy string into the canonical live-state image.

An image is the minimal deterministic complete language machine of the policy
with its dead residual removed:

* two histories share a label exactly when every possible continuation has the
  same allowedness, so the labels are the states of the minimal DFA;
* label 0 is the residual of the empty history (START);
* residuals that cannot reach an allowed sequence are dropped and every
  transition into them becomes the target ``DENY``;
* the retained residuals are numbered by breadth first discovery from START,
  considering the columns in increasing service label order.

The language of a policy is the union of the allow rules minus the union of
the drop rules; a sequence is allowed when at least one allow rule matches and
no drop rule matches.
"""
from ..compiler import engine
from ..compiler.compiler import atom_dfa
from ..syntax import PolicyError, parse_cached, paths_of

#: A stage whose image would need more rows is rejected.
MAX_ROWS = 8192

#: Target of a transition that can never be taken.
DENY = engine.DENY

_ATOM_KINDS = ('match', 'startswith', 'endswith', 'contains')


def _to_nnf(predicate, negated=False):
    """Push negations down to the atoms."""
    kind = predicate[0]
    if kind in _ATOM_KINDS:
        return (kind, predicate[1], negated)
    if kind == 'not':
        return _to_nnf(predicate[1], not negated)
    if kind == 'and':
        if negated:
            return ('or', _to_nnf(predicate[1], True), _to_nnf(predicate[2], True))
        return ('and', _to_nnf(predicate[1], False), _to_nnf(predicate[2], False))
    if kind == 'or':
        if negated:
            return ('and', _to_nnf(predicate[1], True), _to_nnf(predicate[2], True))
        return ('or', _to_nnf(predicate[1], False), _to_nnf(predicate[2], False))
    raise PolicyError('unknown predicate')


def _leaves(node, out):
    kind = node[0]
    if kind in _ATOM_KINDS:
        out.append(node)
    elif kind == 'not':
        _leaves(node[1], out)
    else:
        _leaves(node[1], out)
        _leaves(node[2], out)


def _acceptor(node, index):
    """Build the acceptance function of a negation normal form predicate."""
    kind = node[0]
    if kind in _ATOM_KINDS:
        position = index[(kind, node[1], node[2])]
        if node[2]:
            return lambda flags: not flags[position]
        return lambda flags: bool(flags[position])
    if kind == 'and':
        left = _acceptor(node[1], index)
        right = _acceptor(node[2], index)
        return lambda flags: left(flags) and right(flags)
    left = _acceptor(node[1], index)
    right = _acceptor(node[2], index)
    return lambda flags: left(flags) or right(flags)


def rule_dfa(predicate, sigma):
    """Return the DFA of one rule predicate over *sigma*."""
    form = _to_nnf(predicate)
    leaves = []
    _leaves(form, leaves)
    index = {}
    automata = []
    for leaf in leaves:
        key = (leaf[0], leaf[1], leaf[2])
        if key not in index:
            index[key] = len(automata)
            automata.append(engine.complete(atom_dfa(leaf[0], leaf[1], sigma), sigma))
    if len(automata) == 1:
        if form[2]:
            return engine.complement(automata[0], sigma)
        return automata[0]
    return engine.product(automata, _acceptor(form, index), sigma)


def _compile(text, registry):
    """Compile *text* for *registry* and return the canonical image."""
    ok, parsed = parse_cached(text)
    if not ok:
        raise parsed
    rules = parsed[0]
    sigma = [service['name'] for service in
             sorted(registry, key=lambda service: service['label'])]
    known = set(sigma)
    for predicate, _ in rules:
        for path in paths_of(predicate):
            for name in path:
                if name not in known:
                    raise PolicyError('unregistered service')
    allowed = []
    dropped = []
    for predicate, action in rules:
        automaton = rule_dfa(predicate, sigma)
        if action == 'allow':
            allowed.append(automaton)
        else:
            dropped.append(automaton)
    if not allowed:
        # No allow rule means the empty language.
        return {'accept': [False], 'rows': [[DENY] * len(sigma)]}
    language = engine.minimize(engine.union(allowed, sigma), sigma)
    if dropped:
        forbidden = engine.minimize(engine.union(dropped, sigma), sigma)
        language = engine.intersect(language, engine.complement(forbidden, sigma), sigma)
    language = engine.minimize(language, sigma)
    accept, rows = engine.export(language, sigma)
    if len(rows) > MAX_ROWS:
        raise PolicyError('image bound')
    return {'accept': accept, 'rows': rows}


_CACHE = {}


def create(text, registry):
    """Compile *text* into the canonical image for *registry*.

    *registry* is the list of ``{'name': NAME, 'label': LABEL}`` services.  A
    :class:`~syntax.PolicyError` is raised when the policy violates the
    language, names an unregistered service or needs more than
    :data:`MAX_ROWS` rows.
    """
    key = (text, tuple(sorted((service['name'], service['label'])
                              for service in registry)))
    cached = _CACHE.get(key)
    if cached is not None:
        if isinstance(cached, PolicyError):
            raise cached
        return cached
    try:
        image = _compile(text, registry)
    except PolicyError as exc:
        _CACHE[key] = exc
        raise
    _CACHE[key] = image
    return image
