def export(dfa, sigma):
    """Export the canonical image of a minimal DFA.

    Returns ``(accept, rows)`` where *accept* holds the allowedness of a
    complete history per label and *rows* the transition targets per label and
    column, using :data:`DENY` for the transitions that can never be taken.
    """
    trans = dfa.trans
    finals = dfa.finals
    # Residuals that can reach an allowed sequence.
    reverse = {}
    for state, row in enumerate(trans):
        for target in row.values():
            bucket = reverse.get(target)
            if bucket is None:
                reverse[target] = [state]
            else:
                bucket.append(state)
    live = set(finals)
    stack = list(finals)
    while stack:
        state = stack.pop()
        for source in reverse.get(state, ()):
            if source not in live:
                live.add(source)
                stack.append(source)
    retained = live | set([dfa.start])

    # Breadth first discovery from START, columns in increasing label order.
    label = {dfa.start: 0}
    order = [dfa.start]
    head = 0
    while head < len(order):
        state = order[head]
        head += 1
        row = trans[state]
        for symbol in sigma:
            target = row.get(symbol)
            if target is None or target not in retained or target in label:
                continue
            label[target] = len(order)
            order.append(target)

    rows = []
    accept = []
    for state in order:
        row = trans[state]
        targets = []
        for symbol in sigma:
            target = row.get(symbol)
            if target is None or target not in retained:
                targets.append(DENY)
            else:
                targets.append(label[target])
        rows.append(targets)
        accept.append(state in finals)
    return accept, rows
